from typing import List

class Solution:
    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        # Since the grid is always 3x3, we can check all possible 2x2 squares.
        # There are 3 positions for the top-left corner of a 2x2 square in a 3x3 grid.
        for i in range(3):
            for j in range(3):
                # Extract the 2x2 subgrid starting at (i, j)
                subgrid = [
                    grid[i][j], grid[i][j+1],
                    grid[i+1][j], grid[i+1][j+1]
                ]

                # Check if all cells in the 2x2 subgrid are the same
                if len(set(subgrid)) == 1:
                    return True

        # If no 2x2 square exists with the same color after 0 or 1 changes, return False
        return False
