class Solution:
    def minimumLength(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0

        # Count frequency of each character
        from collections import Counter
        counts = Counter(s)

        # Use a set to track remaining characters
        remaining = set(s)

        while True:
            # Find a character that has both left and right matches
            found = False
            for char in remaining:
                if counts[char] > 0:
                    # Check if there's at least one occurrence to the left
                    left_count = 0
                    # Check from left to right
                    for i, c in enumerate(s):
                        if c == char and i < len(s) - 1:
                            left_count += 1

                    # Check if there's at least one occurrence to the right
                    right_count = 0
                    # Check from right to left
                    for i in range(len(s) - 1, -1, -1):
                        if s[i] == char and i > 0:
                            right_count += 1

                    if left_count > 0 and right_count > 0:
                        # Perform operation
                        # Remove one occurrence to the left
                        # Remove one occurrence to the right
                        # Update counts
                        counts[char] -= 2
                        remaining.remove(char)
                        found = True
                        break

            if not found:
                break

        return len(remaining)
