class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0

        # Iterate over all possible starting positions
        for left in range(n):
            # For each starting position, count how many characters can be appended
            # such that the substring satisfies the k-constraint
            current_len = 0
            for right in range(left, n):
                char = s[right]
                if char == '0':
                    current_len += 1
                else:
                    current_len += 1

                # Check if the substring s[left:right+1] satisfies the k-constraint
                if current_len <= k:
                    count += 1
                else:
                    # If the constraint is violated, break since adding more characters
                    # will not help satisfy the constraint
                    break

        return count
```

