class Solution:
    def maxHeightOfTriangle(self, red: int, blue: int) -> int:
        if red == 0 or blue == 0:
            return max(red, blue)

        # Greedy approach: try to build as many rows as possible
        # Row i has i balls, so we can place min(red, i) red balls and min(blue, i) blue balls
        # We stop when we can no longer form a valid row

        height = 0
        for i in range(1, 101):  # rows 1 to 100 (since max balls = 100)
            red_available = min(red, i)
            blue_available = min(blue, i)

            if red_available == 0 and blue_available == 0:
                break

            if red_available + blue_available == 0:
                break

            # Check if we can form a valid triangle with this height
            # A valid triangle requires that for each row j (1-indexed),
            # the number of red balls used in row j <= number of red balls available
            # and similarly for blue. Since adjacent rows must have different colors,
            # we just need to ensure we don't run out of balls in any row.

            if red_available + blue_available <= i:
                height += 1
                red -= red_available
                blue -= blue_available
            else:
                break

        return height
```

