class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        total_weight = n * w

        if total_weight <= maxWeight:
            return n * n

        # Binary search for the maximum number of containers
        left, right = 0, n * n
        ans = 0

        while left <= right:
            mid = (left + right) // 2
            if mid * w <= maxWeight:
                ans = mid
                left = mid + 1
            else:
                right = mid - 1

        return ans
