class Solution:
    def getEncryptedString(self, s: str, k: int) -> str:
        n = len(s)
        # Precompute the next k characters for each position
        # encrypted[i] will be the k-th character after s[i]
        encrypted = [None] * n

        for i in range(n):
            idx = (i + k) % n
            encrypted[i] = s[idx]

        return "".join(encrypted)
