    def findXSum(self, nums: List[int], k: int, x: int) -> List[int]:
        n = len(nums)
        # Precompute frequencies and sort for each window of size k
        # We'll use a dictionary to store frequency of each element in the current window
        # and a list of (frequency, value) tuples to determine top x elements.

        def get_x_sum(subarray: List[int]) -> int:
            # Count frequencies
            freq = {}
            for v in subarray:
                freq[v] = freq.get(v, 0) + 1

            # Build list of (frequency, value)
            elements = [(freq[v], v) for v in freq]

            # Sort by frequency descending, then by value descending
            elements.sort(key=lambda p: (-p[0], -p[1]))

            # Take top x elements
            if len(elements) < x:
                return sum(subarray)

            return sum(v for _, v in elements[:x])

        # Compute x-sum for each window of size k
        answer = []
        for i in range(n - k + 1):
            answer.append(get_x_sum(nums[i:i+k]))

        return answer
