class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # Precompute the cost to transform s[i] into s[j]
        # cost[i][j] = number of operations to make s[i] == s[j]
        cost = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    cost[i][j] = 0
                else:
                    if s[i] == s[j]:
                        cost[i][j] = 0
                    else:
                        # Compute cost for adjacent characters
                        if abs(ord(s[i]) - ord(s[j])) == 1:
                            cost[i][j] = 1
                        else:
                            cost[i][j] = 1 + cost[i][j-1] + cost[j+1][j]

        # DP state: dp[i][j] = max length of palindrome subsequence
        # in s[i...j] with at most k operations.
        # We use a 1D array for space optimization, but since n <= 200,
        # a 2D DP is acceptable and clearer.
        dp = [[0] * (n + 1) for _ in range(n + 1)]

        for length in range(1, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                # If characters match, no cost
                if s[i] == s[j]:
                    dp[i][j] = dp[i+1][j-1] + 1
                else:
                    # Try all possible split points
                    best = 0
                    for mid in range(i, j + 1):
                        # Left part: s[i...mid]
                        # Right part: s[mid+1...j]
                        # We need to find the best palindrome length for each part
                        # with their respective costs, then combine.
                        # However, a simpler approach for this problem:
                        # The cost to make s[i...mid] and s[mid+1...j] equal is not directly
                        # additive. Instead, we can iterate over all possible target characters c
                        # and compute the cost to make s[i...mid] and s[mid+1...j] both equal to c,
                        # then take the maximum over all c.

                        best = max(best, self._compute_cost_with_target(s, i, mid, k))
                        best = max(best, self._compute_cost_with_target(s, mid+1, j, k))

                    dp[i][j] = best + 1

        return dp[0][n-1]

    def _compute_cost_with_target(self, s: str, i: int, j: int, k: int) -> int:
        # Compute cost to make s[i...j] equal to some character c
        # with at most k operations.
        min_ops = float('inf')
        for c in range(ord('a'), ord('z') + 1):
            # Count operations to make s[x] == c for all x in i...j
            ops = 0
            for x in range(i, j + 1):
                if s[x] != chr(c):
                    ops += 1
            if ops <= k:
                min_ops = min(min_ops, ops)
        return min_ops
