class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        n = len(words)
        m = len(target)

        # Precompute all valid prefixes for each word
        # valid_prefixes[i] = list of (length, word_index)
        valid_prefixes = []
        for i, w in enumerate(words):
            for l in range(1, len(w) + 1):
                valid_prefixes.append((l, i))

        # Sort by length ascending
        valid_prefixes.sort(key=lambda x: x[0])

        # Build a map: prefix_length -> list of word_indices that have this prefix
        prefix_to_words = {}
        for l, idx in valid_prefixes:
            if l not in prefix_to_words:
                prefix_to_words[l] = []
            prefix_to_words[l].append(idx)

        # BFS to find minimum number of valid strings
        # dist[length] = minimum number of valid strings to form a prefix of length 'length'
        dist = {0: 0}
        queue = [0]

        while queue:
            length = queue.pop(0)
            d = dist[length]

            # Try to extend each valid prefix of length 'length'
            for l, idx in prefix_to_words[length]:
                new_length = length + l
                if new_length <= m:
                    if new_length not in dist or d + 1 < dist[new_length]:
                        dist[new_length] = d + 1
                        queue.append(new_length)

        # Check if target can be fully formed
        if m not in dist:
            return -1

        return dist[m]
