class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        MOD = 10**9 + 7

        # Precompute prefix XORs for each cell to quickly compute XOR of a path
        # prefix_xor[i][j] = XOR of all cells from (0,0) to (i,j) inclusive
        prefix_xor = [[0] * n for _ in range(m)]
        prefix_xor[0][0] = grid[0][0]
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                if i > 0:
                    prefix_xor[i][j] ^= grid[i][j]
                if j > 0:
                    prefix_xor[i][j] ^= prefix_xor[i][j-1]

        # dp[i][j] = number of paths from (0,0) to (i,j) with XOR sum equal to prefix_xor[i][j]
        dp = [[0] * n for _ in range(m)]

        # Base case: (0,0)
        if grid[0][0] == k:
            dp[0][0] = 1

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue

                # Try moving from left
                if j > 0:
                    prev_xor = prefix_xor[i][j-1]
                    if prev_xor ^ grid[i][j] == k:
                        dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD

                # Try moving from up
                if i > 0:
                    prev_xor = prefix_xor[i-1][j]
                    if prev_xor ^ grid[i][j] == k:
                        dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD

        return dp[m-1][n-1]
