class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        if not points:
            return 0

        # Sort points by x-coordinate, then by y-coordinate
        points.sort(key=lambda p: (p[0], p[1]))

        n = len(points)
        max_area = 0

        # For each pair of points with same x-coordinate, they can form a vertical edge
        # We iterate over all pairs of points that share the same x-coordinate
        for i in range(n):
            for j in range(i + 1, n):
                if points[i][0] == points[j][0]:
                    # Found two points with same x-coordinate
                    x1, y1 = points[i]
                    x2, y2 = points[j]

                    # Calculate width
                    width = abs(x1 - x2)

                    # Check if there are any points strictly between y1 and y2
                    # that have the same x-coordinate
                    found_interior = False
                    for k in range(i + 1, j):
                        if points[k][0] == x1:
                            if y1 < points[k][1] < y2:
                                found_interior = True
                                break

                    if not found_interior:
                        # Check if there are any points strictly between x1 and x2
                        # that have the same y-coordinate
                        found_interior_y = False
                        for k in range(j + 1, n):
                            if points[k][0] == x2:
                                if x1 < points[k][0] < x2:
                                    found_interior_y = True
                                    break

                        if not found_interior_y:
                            height = abs(y1 - y2)
                            area = width * height
                            max_area = max(max_area, area)

        return max_area
