class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        def count_non_special(n: int) -> int:
            # A number is special if it has exactly 2 proper divisors.
            # Proper divisors are all divisors of n except n itself.
            # So we need to count divisors of n and check if count - 1 == 2 => count == 3.
            # Since n is positive, total divisors = count.
            # We can compute number of divisors by iterating up to sqrt(n).
            if n <= 1:
                return 0  # No positive divisors for 0 or 1 (proper divisors count is 0)

            count = 0
            i = 1
            while i * i <= n:
                if n % i == 0:
                    if i * i == n:
                        count += 1
                    else:
                        count += 2
                i += 1
            return count

        def is_special(n: int) -> bool:
            return count_non_special(n) == 3

        # Count numbers in [l, r] that are NOT special
        # = total numbers - count of special numbers in [l, r]
        return (r - l + 1) - count_special_in_range(l, r)

    def count_special_in_range(self, l: int, r: int) -> int:
        return sum(1 for n in range(l, r + 1) if is_special(n))
