        # Precompute palindromic substrings for t
        def get_palindromes(t: str) -> list:
            palindromes = []
            for i in range(m):
                for j in range(i, m):
                    if t[i:j+1] == t[i:j+1][::-1]:
                        palindromes.append((i, j, t[i:j+1]))
            return palindromes

        s_palindromes = get_palindromes(s)
        t_palindromes = get_palindromes(t)

        # For each palindrome in s, try to extend it with a palindrome from t
        # that matches the reverse of the current palindrome
        for s_pal in s_palindromes:
            s_start, s_end, s_str = s_pal
            s_rev = s_str[::-1]

            # Find the longest palindrome in t that matches s_rev
