class Solution:
    def minAnagramLength(self, s: str) -> int:
        from collections import Counter

        # Count frequency of each character in s
        count = Counter(s)

        # If all characters are distinct, the minimum length is the length of s
        if len(count) == len(s):
            return len(s)

        # If there are duplicate characters, we can potentially reduce the length
        # by pairing up identical characters
        min_len = 0
        for char, freq in count.items():
            if freq > 1:
                min_len += 1
            else:
                break

        return min_len
