class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # dp[i][j] = maximum points after exactly i days ending at city j
        # Initialize with -1 to indicate unvisited states
        dp = [[-1] * n for _ in range(k + 1)]

        # Base case: day 0, can start at any city
        for j in range(n):
            dp[0][j] = stayScore[0][j]

        # Fill DP table for k days
        for day in range(1, k + 1):
            for curr in range(n):
                if dp[day-1][curr] == -1:
                    continue

                # Option 1: Stay in current city
                stay = stayScore[day][curr]
                dp[day][curr] = max(dp[day][curr], dp[day-1][curr] + stay)

                # Option 2: Move to another city
                for dest in range(n):
                    if curr == dest:
                        continue
                    move = travelScore[day][curr][dest]
                    if dp[day-1][curr] != -1:
                        dp[day][dest] = max(dp[day][dest], dp[day-1][curr] + move)

        # The answer is the maximum value in the last day's DP table
        return max(dp[k])
