from typing import List

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        if k == 0:
            return len(set(nums))

        # Sort the array to group identical numbers together
        nums_sorted = sorted(nums)

        # Count consecutive runs of identical numbers
        runs = []
        if nums_sorted:
            current_run = [nums_sorted[0]]
            for i in range(1, len(nums_sorted)):
                if nums_sorted[i] == nums_sorted[i-1]:
                    current_run.append(nums_sorted[i])
                else:
                    runs.append(current_run)
                    current_run = [nums_sorted[i]]
            runs.append(current_run)

        # If k is large enough, we can take all elements
        if k >= len(runs) - 1:
            return sum(len(r) for r in runs)

        # We need to drop at most k runs to maximize the total length
        # Since we want to maximize length, we should drop the smallest runs
        # (which have the fewest elements)
        runs.sort(key=len)

        # Drop the smallest runs, keeping the rest
        dropped = len(runs) - k
        return sum(len(r) for r in runs[:len(runs) - dropped])
