class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Build adjacency list
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                # Count distinct common elements
                common = set()
                for x in properties[i]:
                    if x in properties[j]:
                        common.add(x)
                if len(common) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Count connected components using BFS/DFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                stack = [i]
                while stack:
                    u = stack.pop()
                    visited[u] = True
                    for v in adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            stack.append(v)

        return components
